import React from "react";

const reports = [
{
id:1,
title:"Overflowing Bin",
location:"Sector 4"
},
{
id:2,
title:"Waste not collected",
location:"Zone B"
}
];

const ReportsTab = () => {

return (

<div className="w-full max-w-[900px]">

<h2 className="text-5xl font-black italic text-[#47510B] mb-10">
Citizen Reports
</h2>

<div className="space-y-5">

{reports.map((r)=>(
<div
key={r.id}
className="bg-white p-6 rounded-3xl shadow-lg flex justify-between items-center"
>

<div>

<h3 className="text-xl font-black text-[#47510B] italic">
{r.title}
</h3>

<p className="text-xs font-bold text-[#47510B]/60">
{r.location}
</p>

</div>

<button className="bg-[#FF5B03] text-white px-6 py-3 rounded-xl font-black">
RESOLVE
</button>

</div>
))}

</div>

</div>

);
};

export default ReportsTab;
